    /// <summary>The four materials every Backyard robot is built from. Three are SHARED across the
    /// whole roster — which is what makes seven kinds read as one family assembled from one shed —
    /// and only <see cref="Warm"/> varies, because it is the one carrying gameplay information.</summary>
    public readonly struct RobotPalette
    {
        /// <summary>The kind's own hue, straight from CharacterSkin. The gameplay colour code.</summary>
        public readonly Material Warm;
        /// <summary>Shared cool. Identical on every kind.</summary>
        public readonly Material Cool;
        /// <summary>Shared near-black: every joint, leg, claw, cable and eye bezel.</summary>
        public readonly Material Dark;
        /// <summary>The single Tier-1 gold tell. It foreshadows the Curator and only pays if withheld.</summary>
        public readonly Material Gold;

        public RobotPalette(Material warm, Material cool, Material dark, Material gold)
        {
            Warm = warm; Cool = cool; Dark = dark; Gold = gold;
        }
    }

    /// <summary>
    /// Every Backyard robot's visible body, in metres, feet at y = 0 and +Z where it is running.
    ///
    /// Built from <see cref="CharacterMeshes"/>, not primitives — see that class for why. Two
    /// consequences worth knowing: the geometry is shared across every instance of a kind, so a
    /// swarm costs what one robot costs; and SIZE IS REAL here, because
    /// <c>ParentScale.MakeMetreSpace</c> cancels the archetype's body scale before any of this is
    /// placed. That cancellation is why Rusher, Heavy and Brute used to be the same size on screen
    /// despite three different <c>BodyScale</c> values.
    /// </summary>
    public static class RobotBodies
    {
        /// <summary>Build <paramref name="kind"/>'s body under <paramref name="root"/> and return the
        /// emissive lenses the rig drives as its tell.</summary>
        public static Body Build(EnemyKind kind, Transform root, in RobotPalette p)
        {
            var eyes = new List<MeshRenderer>(2);
            var wheels = new List<Transform>(6);
            switch (kind)
            {
                case EnemyKind.Launcher: BuildLauncher(root, p, eyes, wheels); break;
                case EnemyKind.Blinker:  BuildBlinker(root, p, eyes, wheels); break;
                case EnemyKind.Gunner:   BuildGunner(root, p, eyes, wheels); break;
                case EnemyKind.Bruiser:  BuildBruiser(root, p, eyes, wheels); break;
                case EnemyKind.Heavy:    BuildHeavy(root, p, eyes, wheels); break;
                case EnemyKind.Brute:    BuildBrute(root, p, eyes, wheels); break;
                default:                 BuildRusher(root, p, eyes, wheels); break;
            }
            return new Body(eyes.ToArray(), wheels.ToArray());
        }

        /// <summary>What a built body hands back: the lenses the eye tell drives, and the wheels the
        /// rig spins. Wheels are returned rather than found by name because a name search is a
        /// silent-failure mode — rename a part and the robot stops rolling with no error.</summary>
        public readonly struct Body
        {
            public readonly MeshRenderer[] Eyes;
            /// <summary>Every rolling part, already oriented so its LOCAL Y is the axle. Spin with
            /// <c>Rotate(Vector3.up, degrees, Space.Self)</c>.</summary>
            public readonly Transform[] Wheels;

            public Body(MeshRenderer[] eyes, Transform[] wheels) { Eyes = eyes; Wheels = wheels; }
        }

