            eyes.Add(Lens(root, CharacterMeshes.Sphere(20), new Vector3(-0.06f, 1.5618f, 0.2522f), Quaternion.Euler(-44f, 0f, 0f), new Vector3(0.1318f, 0.1318f, 0.0425f)));
